package com.voicetxt.reader;
import android.app.*;import android.os.Bundle;import android.content.Intent;import java.util.*;import java.util.concurrent.atomic.*;
public class ShelfBatchTest extends Instrumentation {
 void check(boolean ok,String msg){if(!ok)throw new AssertionError(msg);}
 void ui(Runnable task){AtomicReference<Throwable> error=new AtomicReference<>();runOnMainSync(()->{try{task.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError(error.get());}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle result=new Bundle();ShelfActivity activity=null;String original=getTargetContext().getSharedPreferences("shelf",0).getString("books","[]");boolean passed=false;try{activity=(ShelfActivity)startActivitySync(new Intent(getTargetContext(),ShelfActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final ShelfActivity a=activity;
 ui(()->{a.books.clear();for(int i=0;i<4;i++)a.books.add(new ShelfActivity.Book("batch_qa_"+i,(i<2?"测试甲":"测试乙")+i,"content://batch-test/"+i,100,0));a.setManage(true);check(!a.removeSelected.isEnabled(),"empty remove enabled");a.toggleBook(a.books.get(0));check(a.selectedBooks.size()==1,"select failed");a.confirmRemove();a.removeDialog.getButton(AlertDialog.BUTTON_NEGATIVE).performClick();check(a.books.size()==4&&a.selectedBooks.size()==1,"cancel changed shelf");a.search.setText("测试乙");a.selectAll.performClick();check(a.selectedBooks.size()==3,"filtered all lost prior selection");a.selectAll.performClick();check(a.selectedBooks.size()==1,"filtered deselect affected hidden selection");a.search.setText("");a.selectAll.performClick();check(a.selectedBooks.size()==4,"all failed");a.selectAll.performClick();check(a.selectedBooks.isEmpty(),"deselect all failed");a.toggleBook(a.books.get(1));a.toggleBook(a.books.get(3));a.confirmRemove();a.removeDialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick();});waitForIdleSync();ui(()->{check(a.books.size()==2&&a.selectedBooks.isEmpty(),"batch remove failed");a.loadBooks();check(a.books.size()==2&&a.books.get(0).id.equals("batch_qa_0")&&a.books.get(1).id.equals("batch_qa_2"),"removal persistence/order incorrect");a.onBackPressed();check(!a.manage,"back did not exit management");a.setManage(true);a.toggleBook(a.books.get(0));a.setManage(false);check(a.selectedBooks.isEmpty(),"exit retained selections");});passed=true;result.putString("result","PASS: multiple select; filtered select/deselect; all; cancel; batch removal persistence and remaining order; back exits management; exit clears selection");
 }catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));}finally{getTargetContext().getSharedPreferences("shelf",0).edit().putString("books",original).commit();if(activity!=null){final ShelfActivity a=activity;ui(()->{if(a.removeDialog!=null)a.removeDialog.dismiss();a.finish();});}}finish(passed?-1:0,result);}
}
